# owner: platform
import unittest
from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))

class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Brisa", "mon", 9, 12),
            make_shift("Corin", "mon", 9, 17),
            make_shift("Brisa", "tue", 9, 11)
        ]
        self.assertEqual(
            timesheet_rows(shifts),
            [
                "Corin: 1 shift, 8.0 hours",
                "Brisa: 2 shifts, 5.0 hours"
            ]
        )

    def test_one_decimal(self):
        shifts = [Shift("Brisa", "mon", Span(540, 620))]
        self.assertEqual(
            timesheet_rows(shifts),
            ["Brisa: 1 shift, 1.3 hours"]
        )

    def test_ties_break_on_name(self):
        shifts = [
            make_shift("Zane", "mon", 9, 11),
            make_shift("Adel", "mon", 9, 11)
        ]
        rows = timesheet_rows(shifts)
        self.assertTrue(rows[0].startswith("Adel"))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        shifts = [
            make_shift("Brisa", "mon", 9, 12),
            make_shift("  ", "mon", 9, 12)
        ]
        with self.assertRaises(ProjectError):
            timesheet_rows(shifts)
